-- ChubbyLu Bakery POS v0.16.0 — production batches and waste
create table if not exists public.production_batches(id uuid primary key default gen_random_uuid(),batch_number bigint generated by default as identity,shop_id uuid not null references public.shops(id) on delete cascade,product_id uuid not null references public.products(id) on delete restrict,product_name text not null,status text not null default 'scheduled' check(status in('scheduled','completed','cancelled')),scheduled_date date not null,planned_quantity numeric(12,3) not null check(planned_quantity>0),actual_quantity numeric(12,3) check(actual_quantity>=0),waste_quantity numeric(12,3) check(waste_quantity>=0),note text,completion_note text,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),completed_by uuid references auth.users(id) on delete restrict,completed_at timestamptz,cancelled_by uuid references auth.users(id) on delete restrict,cancelled_at timestamptz,constraint production_completion_fields check((status='scheduled' and completed_at is null and cancelled_at is null) or(status='completed' and actual_quantity is not null and waste_quantity is not null and completed_at is not null)or(status='cancelled' and cancelled_at is not null)));
create index if not exists production_batches_shop_schedule_idx on public.production_batches(shop_id,scheduled_date desc);alter table public.production_batches enable row level security;create policy production_batches_admin_select on public.production_batches for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.schedule_production_batch(p_product_id uuid,p_scheduled_date date,p_planned_quantity numeric,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_name text;v_id uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_scheduled_date is null or p_planned_quantity is null or p_planned_quantity<=0 then raise exception 'Valid date and planned quantity are required';end if;select name into v_name from public.products where id=p_product_id and shop_id=v_shop and active;if v_name is null then raise exception 'Active product not found';end if;insert into public.production_batches(shop_id,product_id,product_name,scheduled_date,planned_quantity,note,created_by) values(v_shop,p_product_id,v_name,p_scheduled_date,p_planned_quantity,nullif(trim(p_note),''),auth.uid()) returning id into v_id;return v_id;end $$;

create or replace function public.complete_production_batch(p_batch_id uuid,p_actual_quantity numeric,p_waste_quantity numeric,p_completion_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_batch public.production_batches%rowtype;v_stock numeric;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_actual_quantity is null or p_waste_quantity is null or p_actual_quantity<0 or p_waste_quantity<0 or p_actual_quantity+p_waste_quantity<=0 then raise exception 'Valid sellable and waste quantities are required';end if;select * into v_batch from public.production_batches where id=p_batch_id and shop_id=v_shop for update;if v_batch.id is null or v_batch.status<>'scheduled' then raise exception 'Scheduled batch not found';end if;update public.products set stock=stock+p_actual_quantity,updated_at=now() where id=v_batch.product_id and shop_id=v_shop returning stock into v_stock;update public.production_batches set status='completed',actual_quantity=p_actual_quantity,waste_quantity=p_waste_quantity,completion_note=nullif(trim(p_completion_note),''),completed_by=auth.uid(),completed_at=now() where id=v_batch.id;insert into public.inventory_adjustments(shop_id,product_id,delta,reason,created_by) values(v_shop,v_batch.product_id,p_actual_quantity,'Production batch B-'||v_batch.batch_number||' completed; waste '||p_waste_quantity,auth.uid());return jsonb_build_object('batch_id',v_batch.id,'product_id',v_batch.product_id,'new_stock',v_stock);end $$;

create or replace function public.cancel_production_batch(p_batch_id uuid) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;update public.production_batches set status='cancelled',cancelled_by=auth.uid(),cancelled_at=now() where id=p_batch_id and shop_id=v_shop and status='scheduled';if not found then raise exception 'Scheduled batch not found';end if;end $$;

create or replace function public.get_production_batches() returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;return(select coalesce(jsonb_agg(to_jsonb(x) order by x.scheduled_date desc,x.created_at desc),'[]'::jsonb) from(select b.id,b.batch_number,b.product_id,b.product_name,b.status,b.scheduled_date,b.planned_quantity,b.actual_quantity,b.waste_quantity,b.note,b.completion_note,b.created_at,b.completed_at,coalesce(cp.display_name,'Former staff') created_by_name,ep.display_name completed_by_name from public.production_batches b left join public.staff_profiles cp on cp.user_id=b.created_by and cp.shop_id=b.shop_id left join public.staff_profiles ep on ep.user_id=b.completed_by and ep.shop_id=b.shop_id where b.shop_id=v_shop order by b.scheduled_date desc,b.created_at desc limit 200)x);end $$;
revoke all on function public.schedule_production_batch(uuid,date,numeric,text) from public;revoke all on function public.complete_production_batch(uuid,numeric,numeric,text) from public;revoke all on function public.cancel_production_batch(uuid) from public;revoke all on function public.get_production_batches() from public;grant execute on function public.schedule_production_batch(uuid,date,numeric,text) to authenticated;grant execute on function public.complete_production_batch(uuid,numeric,numeric,text) to authenticated;grant execute on function public.cancel_production_batch(uuid) to authenticated;grant execute on function public.get_production_batches() to authenticated;
